mapper.select:
/* DayTemporaryDtlSaleMapper.getDayTemporaryDtlSaleList */

SELECT  TO_CHAR(TO_DATE(A.SALE_DATE, 'yyyymmdd'), 'yyyy-mm-dd') AS SALE_DATE
,       TO_CHAR(TO_DATE(A.SALE_DATE, 'yyyymmdd'), 'DY') AS YOIL
,       TMS.BRANCH_CD
,       (SELECT BRANCH_NM FROM TB_HQ_BRANCH_MOMS THBM WHERE THBM.HQ_OFFICE_CD = #{hqOfficeCd} AND THBM.BRANCH_CD = TMS.BRANCH_CD) AS BRANCH_NM
,       A.STORE_CD
,       TMS.STORE_NM
,       SUM(CASE WHEN A.SALE_YN = 'Y' THEN 1 WHEN A.SALE_YN = 'N' THEN -1 ELSE 0 END) AS TEMPORARY_PAY_CNT
,       SUM(A.SALE_AMT) AS TOT_SALE_AMT

,       SUM(CASE WHEN A.TEMPORARY_PAY_CD = #{item.nmcodeCd} THEN A.SALE_AMT ELSE 0 END) AS TEMPORARY_PAY${item.nmcodeCd}


FROM    TB_SL_SALE_PAY_TEMPORARY A
,       TB_MS_STORE TMS
,       TB_MS_STORE_INFO TMSI
,       (
            SELECT  B.NMCODE_ITEM_1 AS NMCODE_CD
            FROM    TB_CM_NMCODE B
            WHERE   B.NMCODE_GRP_CD = '248'
            AND     B.NMCODE_NM = '매장별가승인매출'
        ) TP
WHERE   A.HQ_OFFICE_CD = #{hqOfficeCd}

    AND A.STORE_CD IN (${storeCdQuery})

AND     A.SALE_DATE BETWEEN #{startDate} AND #{endDate}
AND     A.HQ_OFFICE_CD = TMS.HQ_OFFICE_CD
AND     A.STORE_CD = TMS.STORE_CD
AND     A.STORE_CD = TMSI.STORE_CD (+)
AND     A.TEMPORARY_PAY_CD = TP.NMCODE_CD

    AND TMS.HQ_BRAND_CD = #{storeHqBrandCd} -- 매장브랜드 선택일때



        -- 매장브랜드 전체일때
        AND TMS.HQ_BRAND_CD IN

            #{item}




    AND TMSI.MOMS_TEAM = #{momsTeam}


    AND TMSI.MOMS_AC_SHOP = #{momsAcShop}


    AND TMSI.MOMS_AREA_FG = #{momsAreaFg}


    AND TMSI.MOMS_COMMERCIAL = #{momsCommercial}


    AND TMSI.MOMS_SHOP_TYPE = #{momsShopType}


    AND TMSI.MOMS_STORE_MANAGE_TYPE = #{momsStoreManageType}


    AND TMS.BRANCH_CD = #{branchCd}


    AND TMSI.MOMS_STORE_FG_01 = #{momsStoreFg01}


    AND TMSI.MOMS_STORE_FG_02 = #{momsStoreFg02}


    AND TMSI.MOMS_STORE_FG_03 = #{momsStoreFg03}


    AND TMSI.MOMS_STORE_FG_04 = #{momsStoreFg04}


    AND TMSI.MOMS_STORE_FG_05 = #{momsStoreFg05}

GROUP
BY      A.SALE_DATE
,       TMS.BRANCH_CD
,       A.STORE_CD
,       TMS.STORE_NM
ORDER
BY      A.SALE_DATE DESC
,       A.STORE_CD
